#!/usr/bin/env bash
# Byte-identity gate for the CPU --video worker pool (--cpu-threads).
#
# Encodes the same synthetic P-frame sequence with 1, 2 and 4 workers, with and
# without a 2x2 tile grid, and requires identical IVF MD5s.  The input is
# generated by tests/gen_y4m.cpp (integer pattern, identical on every host), so
# no media fixture is needed.
#
# Usage: multithread_identity.sh <av2enc-binary> <gen_y4m-binary>
#
# Exit 77 (skip) when dav2d is unavailable for the decode check; the stream
# identity check itself never skips.
set -euo pipefail

if [ $# -ne 2 ]; then
    echo "usage: $0 <av2enc-binary> <gen_y4m-binary>" >&2
    exit 2
fi

BIN=$1
GEN=$2
ROOT=$(cd "$(dirname "$0")/.." && pwd)
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

if [ ! -x "$BIN" ] || [ ! -x "$GEN" ]; then
    echo "error: missing binaries: $BIN $GEN" >&2
    exit 2
fi

# 192x128 is a 3x2 superblock grid, so the partition walk, the NEWMV batch and
# a 2x2 tile grid all get exercised.  Repeat the single generated frame to make
# a P-frame sequence.
"$GEN" 192 128 "$TMP/frame.y4m"
{
    head -n 1 "$TMP/frame.y4m"
    for _ in 1 2 3 4 5 6; do
        tail -n +2 "$TMP/frame.y4m"
    done
} > "$TMP/seq.y4m"

md5_of() {
    if command -v md5 >/dev/null 2>&1; then
        md5 -q "$1"
    else
        md5sum "$1" | cut -d' ' -f1
    fi
}

run_case() {
    local name=$1
    shift
    local ref=""
    for threads in 1 2 4; do
        local out="$TMP/${name}_t${threads}.ivf"
        "$BIN" "$TMP/seq.y4m" -o "$out" --video --frames 6 --qp 120 \
            --cpu-threads "$threads" "$@" >/dev/null
        local digest
        digest=$(md5_of "$out")
        if [ -z "$ref" ]; then
            ref=$digest
            echo "  ${name}: ${digest} (t1)"
        elif [ "$digest" != "$ref" ]; then
            echo "error: ${name} t${threads} md5 ${digest} != t1 ${ref}" >&2
            return 1
        else
            echo "  ${name}: ${digest} (t${threads}, identical)"
        fi
    done
    # Decoder sanity on a parallel stream.  Stream identity already implies
    # identical reconstruction; this catches an unparsable IVF header.
    if [ "${DAV2D:-}" != "" ] || [ -x "$ROOT/tools/bin/dav2d-macos" ]; then
        DAV2D="${DAV2D:-$ROOT/tools/bin/dav2d-macos}" \
            "$ROOT/tools/validate_dav2d.sh" "$TMP/${name}_t4.ivf" \
            >/dev/null || return 1
    fi
    return 0
}

echo "multithread identity: CPU --video worker pool"
run_case whole_frame
run_case tiled_2x2 --tiles 2x2 --no-deblock
echo "multithread identity: ok (byte-identical at 1/2/4 workers)"
